from pathlib import Path
import html,json
from vinyl_template import vinyl_thumbnail
p=Path(__file__).resolve().parent
e=html.escape
music_entries=[x for x in json.loads((p.parent/'sculpture-music.json').read_text()) if x['id'] in ['beethoven-symphony-nine','billie-holiday-strange-fruit','joao-gilberto-chega-saudade']]
movies=[]
if (p/'shotdeck-selections.json').exists():
 data=json.loads((p/'shotdeck-selections.json').read_text())
 movies=data if isinstance(data,list) else data.get('selections',[])
css='''@font-face{font-family:"PP Neue Montreal";src:local("PPNeueMontrealTT-Regular"),local("PP Neue Montreal TT Regular");font-weight:400;font-display:swap}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fff;color:#252525;font:14px/20px "PP Neue Montreal",system-ui,sans-serif}a{color:inherit;text-underline-offset:3px}header{border-bottom:1px solid #f2f2f2;padding:20px 24px;display:flex;align-items:center;justify-content:space-between;gap:20px}main{max-width:1040px;padding:40px 24px 60px;margin:auto}h1{font-size:32px;line-height:40px;font-weight:400;letter-spacing:-.7px;margin:8px 0 12px}h2{font-size:20px;line-height:24px;font-weight:400;margin:0}h3{font-size:16px;line-height:20px;font-weight:400;margin:8px 0 2px}p{max-width:610px}.muted{color:#6e6e6e}.eyebrow{font-size:10px;line-height:12px;color:#6e6e6e;letter-spacing:1px;text-transform:uppercase}.toolbar{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;margin:28px 0 16px}.group{display:flex;gap:4px;align-items:center;font-size:12px;line-height:16px}.group>span{margin-right:8px;color:#6e6e6e}button{font:inherit;cursor:pointer;border:0;background:#f2f2f2;color:#252525;padding:8px 12px;border-radius:20px;min-height:32px}button[aria-pressed=true]{background:#252525;color:white}button:focus-visible,a:focus-visible{outline:2px solid #252525;outline-offset:3px}.objects{display:grid;grid-template-columns:1fr 1fr;gap:24px}.stage{aspect-ratio:1;display:grid;place-items:center;background:var(--stage,#f2f2f2);border-radius:16px;overflow:hidden;border:1px solid #f2f2f2}.stage>img{width:84%;height:84%;object-fit:contain;display:block}.stage.original>img{width:88%;height:88%}.card>p{font-size:12px;line-height:16px;margin:4px 0;color:#6e6e6e}.principles{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;padding:28px 0;border-bottom:1px solid #f2f2f2}.principles p{font-size:12px;line-height:16px;color:#6e6e6e;margin:8px 0}.films{margin-top:36px}.moviegrid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:20px}.frame{aspect-ratio:16/10;display:flex;align-items:center;justify-content:center;background:#f2f2f2;border-radius:8px;overflow:hidden}.frame img{width:100%;height:100%;object-fit:contain}.movie p{font-size:12px;line-height:16px;color:#6e6e6e}details{margin-top:28px;font-size:12px;line-height:18px;color:#6e6e6e}summary{cursor:pointer}footer{font-size:12px;color:#6e6e6e;margin-top:36px;border-top:1px solid #f2f2f2;padding-top:16px}@media(max-width:650px){main{padding:24px 16px}.objects{grid-template-columns:1fr;gap:28px}.principles{grid-template-columns:1fr;gap:12px}.moviegrid{grid-template-columns:1fr}h1{font-size:26px;line-height:32px}header{padding:16px}button{min-height:44px}.toolbar{gap:12px}}'''
css+='''.music{margin-top:36px}.musicgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:20px}.vinyl{position:relative;width:79%;aspect-ratio:1;border-radius:50%;background:repeating-radial-gradient(circle at 50% 50%,#181818 0px,#181818 1px,#2b2b2b 1.5px,#181818 2px,#181818 3px);box-shadow:0 12px 14px -10px #0005,0 2px 3px #0002,inset 0 0 0 2px #111,inset 0 0 0 3px #333}.vinyl:before{content:"";position:absolute;inset:1%;border-radius:50%;background:conic-gradient(from 15deg,transparent 0deg,#ffffff24 38deg,transparent 68deg,transparent 165deg,#ffffff1c 213deg,transparent 242deg);pointer-events:none}.record-label{position:absolute;width:36%;height:36%;left:32%;top:32%;border-radius:50%;overflow:hidden;background:#f2f2f2;box-shadow:0 0 0 4px #141414;isolation:isolate}.record-label img{width:100%;height:100%;object-fit:cover;display:block}.record-label:after{content:"";position:absolute;left:46%;top:46%;width:8%;height:8%;background:var(--stage,#f2f2f2);border-radius:50%;box-shadow:0 0 0 1px #0006}.music .card h3{margin-top:10px}.music .card p{max-width:260px}.music-source{font-size:12px;line-height:16px;color:#6e6e6e;display:inline-block;margin-top:6px}@media(max-width:650px){.musicgrid{grid-template-columns:1fr}.music .stage{max-width:420px;width:100%}}'''
css+='''.film-link{font-size:12px;text-decoration:none}.film-link:hover{background:#eaeaea}.movie p{max-width:290px}'''
objects=[('borobudur','Borobudur','Architecture · Central Java · 8th–9th centuries','A complete architectural form with space around it.'),('buddha','Great Buddha at Tōdai-ji','Sculpture · Nara · First consecration 752','A sculptural silhouette with its material and gesture preserved.')]
obj=''.join(f'<article class="card"><div class="stage object-stage"><img data-key="{key}" src="{key}-study.png" alt="Generated visual study of {e(title)} as an isolated museum object" data-study="{key}-study.png" data-original="references/{key}-reference.jpg"></div><h3>{e(title)}</h3><p>{e(meta)}</p></article>' for key,title,meta,note in objects)
music_cards=[]
labels={'beethoven-symphony-nine':('Symphony No. 9','Ludwig van Beethoven','Manuscript artwork'), 'billie-holiday-strange-fruit':('Strange Fruit','Billie Holiday','Original release label'), 'joao-gilberto-chega-saudade':('Chega de Saudade','João Gilberto','1959 album artwork')}
for item in music_entries:
 title,creator,note=labels[item['id']]
 media=item['media']
 music_cards.append(f'<article class="card">{vinyl_thumbnail(media, item["id"])}<h3>{e(title)}</h3><p>{e(creator)}</p><p>{e(note)}</p></article>')
music='<section class="music" id="music"><div class="eyebrow">Music</div><h2>One vinyl frame</h2><p><a href="music.html">View the music experiment ↗</a></p><p class="muted">The same vinyl photograph, with each work’s artwork at the center.</p><div class="musicgrid">'+''.join(music_cards)+'</div></section>'
films=''
if movies:
 cards=[]
 for m in movies:
  image=m.get('imageUrl') or m.get('directImageUrl')
  if not image:continue
  title=m.get('title') or m.get('filmTitle') or 'Film'
  link=m.get('shotUrl') or m.get('framePageUrl') or m.get('pageUrl') or 'https://shotdeck.com/welcome/home'
  rationale={'I\'m Still Here':'Eunice photographs her family and friends on the beach.','Eternal Sunshine of the Spotless Mind':'Joel and Clementine lie together on the frozen lake.','Soul':'Joe crosses a sunlit New York street.'}.get(title,'Selected frame')
  local=m.get('localImagePath')
  if local and (p/local).is_file():
   frame=f'<a class="frame" href="{e(local,quote=True)}" target="_blank" rel="noopener noreferrer"><img src="{e(local,quote=True)}" alt="{e(m.get("altText",rationale),quote=True)}"></a>'
  else:
   frame=f'<a class="frame film-link" href="{e(link,quote=True)}" target="_blank" rel="noopener noreferrer"><span>View selected frame ↗</span></a>'
  cards.append(f'<article class="movie">{frame}<h3>{e(title)}</h3><p>{e(rationale)}</p></article>')
 if cards:films='<section class="films" id="cinema"><div class="eyebrow">Cinema</div><h2>One frame from the film</h2><p class="muted">Original framing and color, with each film’s proportions preserved.</p><div class="moviegrid">'+''.join(cards)+'</div></section>'
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Daily Culture · Visual study</title><style>'+css+'</style></head><body><header><span>Daily Culture</span><a href="../REVIEW.html">Back to the 21 entries</a></header><main><div class="eyebrow">Visual direction · Study 01</div><h1>A consistent stage for each work</h1><p class="muted">Architecture and sculpture as isolated forms. Music as vinyl records. Cinema through individual frames.</p><div class="toolbar"><div class="group" aria-label="Image treatment"><span>Image</span><button type="button" data-mode="study" aria-pressed="true">Study</button><button type="button" data-mode="original" aria-pressed="false">Original</button></div><div class="group" aria-label="Background"><span>Canvas</span><button type="button" data-bg="#f2f2f2" aria-pressed="true">Light gray</button><button type="button" data-bg="#ffffff" aria-pressed="false">White</button></div></div><div class="objects">'+obj+'</div><div class="principles"><div><h3>Framing</h3><p>One complete form. Clear space around its silhouette.</p></div><div><h3>Light</h3><p>Soft, consistent lighting. Enough shadow to show depth.</p></div><div><h3>Material</h3><p>Keep stone and bronze distinct. Avoid a generic plastic finish.</p></div></div>'+music+films+'<details><summary>Study notes and original references</summary><p>These are generated interpretations for choosing a visual direction. Borobudur’s elevated view reconstructs details unseen in the source. The Buddha study omits the gold halo and reconstructs parts of the pedestal. These details need a fidelity review before publication. The original entry images remain available.</p><p>Borobudur source: Gunawan Kartapranata, 2008, Wikimedia Commons, CC BY-SA 3.0. Great Buddha source: Fg2, Wikimedia Commons, public-domain dedication. Reference records and generation prompts are saved beside this study.</p><p>The vinyls are presentation mockups, not reproductions of historical pressings. Beethoven uses manuscript artwork; Strange Fruit uses its original release label; Chega de Saudade uses the 1959 album cover for the 1958 song recording.</p></details><footer>Visual approval pending.</footer></main><script>document.querySelectorAll("[data-mode]").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll("[data-mode]").forEach(x=>x.setAttribute("aria-pressed",String(x===b)));document.querySelectorAll(".object-stage img").forEach(i=>{i.src=i.dataset[b.dataset.mode];i.parentElement.classList.toggle("original",b.dataset.mode==="original");i.alt=(b.dataset.mode==="original"?"Source photograph of ":"Generated visual study of ")+(i.dataset.key==="borobudur"?"Borobudur":"Great Buddha at Tōdai-ji");});}));document.querySelectorAll("[data-bg]").forEach(b=>b.addEventListener("click",()=>{document.body.style.setProperty("--stage",b.dataset.bg);document.querySelectorAll("[data-bg]").forEach(x=>x.setAttribute("aria-pressed",String(x===b)));}));</script></body></html>'
(p/'index.html').write_text(page)
print('Saved visual study page.')
